"""Commit gate guard: deny(cmd) -> reason or None. Refuses by SHAPE at every token position."""
import re
import shlex

OPS = {";", "&&", "||", "|", "&", "(", ")"}
VALUE_OPTS = {"-m", "--message", "-F", "--file", "-C", "-c", "--author", "--date"}


def _segments(cmd):
    lex = shlex.shlex(cmd, posix=True, punctuation_chars="();|&")
    lex.whitespace_split = True
    seg = []
    for t in lex:
        if t in OPS:
            if seg:
                yield seg
            seg = []
        else:
            seg.append(t)
    if seg:
        yield seg


GIT_GLOBAL_VALUE_OPTS = {"-C", "-c", "--git-dir", "--work-tree", "--namespace", "--exec-path", "--config-env", "--super-prefix"}


def _subcommand(rest):
    """git's own options come before the subcommand; the ones that take a VALUE consume the next token
    (`git -C repo commit`); the `--x=y` forms are one token. Returns (index, name) or (None, None)."""
    j = 0
    while j < len(rest):
        a = rest[j]
        if a in GIT_GLOBAL_VALUE_OPTS:
            j += 2
            continue
        if a.startswith("-"):
            j += 1
            continue
        return j, a
    return None, None


HEREDOC = re.compile(r"<<-?\s*\W?(\w+)\W?(?P<rest>[^\n]*)\n.*?\n\1(?=\n|$)", re.S)
SHORT_VALUE = set("mFCctuS")   # short commit flags that take a value: whatever follows them in the cluster is the VALUE


def _cluster_has_n(a):
    """`-anm"fix 1"` tokenises to `-anmfix 1`: flags are read left to right until the first flag that takes a
    value; everything after that is the value, never a flag. -n before that point is the bypass."""
    for ch in a[1:]:
        if ch == "n":
            return True
        if ch in SHORT_VALUE or not ch.isalpha():
            return False
    return False


def deny(cmd):
    cmd = HEREDOC.sub(lambda m: " HEREDOC " + m.group("rest"), cmd)   # the BODY is data; the rest of its line stays
    cmd = re.sub(r"(\d*>&\d+|&>>?)", " ", cmd)   # fd redirections (2>&1, &>) are not the & operator
    try:
        segments = list(_segments(cmd))
    except ValueError:
        return "unparseable command line (unbalanced quote) — refusing to guess what it runs"   # fail CLOSED
    for seg in segments:
        for i, t in enumerate(seg):
            if t.rsplit("/", 1)[-1] != "git":
                continue   # prefix words (env, nohup, nice -n 5) are skipped, not trusted
            rest = seg[i + 1:]
            k, sub = _subcommand(rest)
            if sub != "commit":
                continue
            args = rest[k + 1:]
            j = 0
            while j < len(args):
                a = args[j]
                if a == "--":
                    break
                if a in VALUE_OPTS:
                    j += 2   # never inspect a value: a message may mention --no-verify
                    continue
                # the long form, any unambiguous abbreviation git accepts (--no-v...), and -n anywhere in a
                # short-flag cluster with or without a value glued on (-anm"fix 1" tokenises to "-anmfix 1")
                if (a.startswith("--no-v") and "--no-verify".startswith(a)) or (a.startswith("-") and not a.startswith("--") and _cluster_has_n(a)):
                    return f"git commit {a!r} skips the pre-commit gate"
                if len(a) > 1 and a.startswith("-") and not a.startswith("--") and any(ch in SHORT_VALUE for ch in a[1:]):
                    pass   # the value is glued on; nothing more to skip
                elif a in VALUE_OPTS:
                    j += 2
                    continue
                j += 1
    return None

