"""Public-file guard: safe_path(root, rel) -> absolute path under root, or None (deny).
Refuses by SHAPE: any `..` segment at any position, any absolute path, the empty path."""
import os


def safe_path(root, rel):
    if not isinstance(rel, str) or rel == "":
        return None
    if rel.startswith("/"):
        return None
    parts = [p for p in rel.split("/") if p not in ("", ".")]
    if not parts or any(p == ".." for p in parts):
        return None
    return os.path.join(os.path.abspath(root), *parts)
